import React, { useRef } from 'react';
import { Sparkles, Play, ShieldCheck, CornerDownLeft } from 'lucide-react';

const SUGGESTIONS = [
  "What are the top 5 most expensive products?",
  "Calculate the total revenue generated by each customer",
  "List all categories with total product count and average price",
  "Show the most recent 10 delivered orders with customer names",
  "Find customers who have spent more than $500",
];

export default function QueryInput({
  prompt,
  setPrompt,
  onSubmit,
  loading,
  databaseType,
}) {
  const textareaRef = useRef(null);

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      if (!loading && prompt.trim()) {
        onSubmit();
      }
    }
  };

  const handleSuggestionClick = (sugg) => {
    setPrompt(sugg);
    if (textareaRef.current) {
      textareaRef.current.focus();
    }
  };

  return (
    <div className="clay-panel" style={{ padding: '1.5rem', marginBottom: '1.75rem' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.85rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Sparkles size={17} color="var(--accent-primary)" />
          <label htmlFor="prompt-input" style={{ fontSize: '0.92rem', fontWeight: '800', letterSpacing: '-0.01em' }}>
            Natural Language Query Prompt
          </label>
        </div>
        <div className="badge badge-success clay-pill" style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', fontSize: '0.72rem' }}>
          <ShieldCheck size={14} />
          <span>AST Deterministic Read-Only</span>
        </div>
      </div>

      <div style={{ position: 'relative' }}>
        <textarea
          id="prompt-input"
          ref={textareaRef}
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={`Ask anything about your ${databaseType.toUpperCase()} database in plain English (e.g. "What are the top 5 most expensive products?")...`}
          rows={3}
          className="clay-carved"
          style={{
            width: '100%',
            padding: '1rem 1.15rem',
            color: 'var(--text-primary)',
            fontSize: '0.95rem',
            fontFamily: 'var(--font-main)',
            resize: 'vertical',
            outline: 'none',
          }}
          onFocus={(e) => e.target.style.borderColor = 'var(--accent-primary)'}
          onBlur={(e) => e.target.style.borderColor = 'var(--border-subtle)'}
        />
      </div>

      {/* Footer bar inside QueryInput */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: '1rem', flexWrap: 'wrap', gap: '0.85rem' }}>
        {/* Suggestion Pills */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap', flex: 1 }}>
          <span style={{ fontSize: '0.74rem', color: 'var(--text-muted)', fontWeight: 700 }}>Try:</span>
          {SUGGESTIONS.map((sugg, idx) => (
            <button
              key={idx}
              type="button"
              className="clay-pill"
              onClick={() => handleSuggestionClick(sugg)}
              style={{
                background: 'var(--clay-btn-secondary-bg)',
                border: '1px solid var(--border-subtle)',
                padding: '0.32rem 0.75rem',
                fontSize: '0.74rem',
                fontWeight: 600,
                color: 'var(--text-secondary)',
                cursor: 'pointer',
                whiteSpace: 'nowrap',
              }}
              onMouseEnter={(e) => {
                e.target.style.borderColor = 'var(--accent-primary)';
                e.target.style.color = 'var(--text-primary)';
              }}
              onMouseLeave={(e) => {
                e.target.style.borderColor = 'var(--border-subtle)';
                e.target.style.color = 'var(--text-secondary)';
              }}
            >
              {sugg}
            </button>
          ))}
        </div>

        {/* Submit Button */}
        <button
          className="btn btn-primary clay-btn-primary"
          onClick={onSubmit}
          disabled={loading || !prompt.trim()}
          style={{ minWidth: '145px', padding: '0.7rem 1.4rem' }}
        >
          {loading ? (
            <>
              <div className="pulse-indicator" style={{ background: '#fff' }} />
              <span>Analyzing...</span>
            </>
          ) : (
            <>
              <Play size={14} fill="#ffffff" />
              <span>Run Query</span>
              <span style={{ opacity: 0.75, fontSize: '0.7rem', display: 'flex', alignItems: 'center' }}>
                <CornerDownLeft size={11} style={{ marginLeft: 3 }} />
              </span>
            </>
          )}
        </button>
      </div>
    </div>
  );
}
